                    padding: '12px 24px',
                    backgroundColor: '#6366f1',
                    color: '#ffffff',
                    border: 'none',
                    borderRadius: '8px',
                    cursor: watchlistSearching ? 'not-allowed' : 'pointer',
                    fontSize: '14px',
                    fontWeight: '500',
