                      return (
                        <div
                          key={symbol}
                          style={{
                            display: 'flex',
                            alignItems: 'center',
                            gap: '8px',
                            padding: '8px 12px',
                            backgroundColor: theme.secondaryBgAlt,
                            borderRadius: '8px',
                            border: `1px solid ${theme.border}`,
