                            onClick={() => addToWatchlistFromSearch(symbol)}
                            style={{
                              padding: '4px 10px',
                              backgroundColor: '#10b981',
                              color: '#ffffff',
                              border: 'none',
                              borderRadius: '4px',
                              cursor: 'pointer',
                              fontSize: '12px',
                              fontWeight: '500',
                            }}
                          >
                            Add
                          </button>
