                      </button>
                    </div>
                    <button
                      onClick={() => briefTicker(ticker)}
                      disabled={loading}
                      style={{
                        width: '100%',
                        padding: '10px',
                        backgroundColor: '#6366f1',
                        color: '#ffffff',
                        border: 'none',
                        borderRadius: '6px',
                        cursor: loading ? 'not-allowed' : 'pointer',
                        fontSize: '14px',
                        fontWeight: '500',
                        marginTop: '8px',
                      }}
                    >
                      {loading && selectedTicker === ticker ? 'Loading...' : 'Brief Me'}
                    </button>
                  </div>
                ))}
              </div>
            )}
          </div>
