                    <div style={{ fontSize: '12px', color: theme.textMuted, marginBottom: '12px' }}>
                      {(article.source && article.source.name) || 'Unknown'} â€¢ {article.publishedAt ? new Date(article.publishedAt).toLocaleDateString() : ''}
                    </div>
