                  </div>
                )}
              </div>
            ) : (
              <div>
                <div
                  style={{
                    padding: '24px',
                    backgroundColor: theme.surface,
                    border: `1px solid ${theme.border}`,
                    borderRadius: '12px',
                    marginBottom: '24px',
                    boxShadow: '0 8px 32px rgba(0, 0, 0, 0.04)',
