                  onKeyPress={(e) => e.key === 'Enter' && searchSocial()}
                  style={{
                    flex: 1,
                    padding: '12px 16px',
                    border: `1px solid ${theme.border}`,
                    borderRadius: '8px',
                    fontSize: '14px',
                    backgroundColor: theme.surface,
                    color: theme.text,
                  }}
                />
                <button
                  onClick={searchSocial}
                  disabled={socialLoading}
                  style={{
                    padding: '12px 24px',
                    backgroundColor: '#6366f1',
                    color: '#ffffff',
                    border: 'none',
                    borderRadius: '8px',
                    cursor: socialLoading ? 'not-allowed' : 'pointer',
                    fontSize: '14px',
                    fontWeight: '500',
