                          border: `1px solid ${theme.border}`,
                          borderRadius: '12px',
                          boxShadow: '0 8px 32px rgba(0, 0, 0, 0.04)',
                        }}
                      >
                        <div style={{ marginBottom: '12px' }}>
                          <a
                            href={linkUrl}
                            target="_blank"
                            rel="noopener noreferrer"
                            style={{
                              fontSize: '16px',
                              fontWeight: '600',
                              color: '#6366f1',
                              textDecoration: 'none',
                              display: 'block',
                              marginBottom: '4px',
                            }}
                          >
                            {result.name || (result.snippet && result.snippet.title) || result.title || 'Unknown'}
                          </a>
                          <div style={{ fontSize: '12px', color: theme.textMuted, marginBottom: '8px' }}>
                            {isLinkedIn ? result.headline : (result.snippet && result.snippet.channelTitle) || (result.snippet && result.snippet.description)}
                          </div>
                          {isLinkedIn && result.location && (
                            <div style={{ fontSize: '11px', color: theme.textMutedLight }}>{result.location}</div>
                          )}
                          {!isLinkedIn && result.snippet && result.snippet.publishedAt && (
                            <div style={{ fontSize: '11px', color: theme.textMutedLight }}>
                              {new Date(result.snippet.publishedAt).toLocaleDateString()}
                            </div>
                          )}
                          <span
                            style={{
                              display: 'inline-block',
                              marginTop: '8px',
                              padding: '4px 8px',
                              backgroundColor: isLinkedIn ? '#0077b5' : '#ff0000',
                              color: '#ffffff',
                              borderRadius: '4px',
                              fontSize: '10px',
                              fontWeight: '500',
                            }}
                          >
                            {isLinkedIn ? 'LinkedIn' : 'YouTube'}
                          </span>
                        </div>
                        <button
                          onClick={() => (isFollowing ? unfollowAccount(result.id || result.channelId || (result.snippet && result.snippet.channelId), result.platform) : followAccount(result))}
                          style={{
                            width: '100%',
                            padding: '8px',
                            backgroundColor: isFollowing ? '#ef4444' : '#6366f1',
                            color: '#ffffff',
                            border: 'none',
                            borderRadius: '6px',
                            cursor: 'pointer',
                            fontSize: '13px',
                            fontWeight: '500',
                          }}
                        >
                          {isFollowing ? 'Following' : '+ Follow'}
                        </button>
                      </div>
                    );
                  })}
                </div>
              </div>
            )}

            {!socialLoading && (!socialResults || socialResults.length === 0) && socialSearchQuery && (
              <div style={{ textAlign: 'center', padding: '40px', color: theme.textMutedLight }}>No results found. Try a different search query.</div>
            )}
          </div>
        )}

        {activeView === 'portfolio' && (
          <div>
            <h2 style={{ fontSize: '24px', fontWeight: '600', marginBottom: '24px' }}>Portfolio</h2>
            <div
              style={{
                padding: '20px',
                backgroundColor: theme.surface,
                border: `1px solid ${theme.border}`,
                borderRadius: '12px',
                marginBottom: '24px',
                boxShadow: '0 8px 32px rgba(0, 0, 0, 0.04)',
              }}
            >
              <div style={{ fontSize: '16px', fontWeight: '600', marginBottom: '12px' }}>Search Stocks</div>
              <div style={{ display: 'flex', gap: '12px', marginBottom: '12px' }}>
                <input
                  type="text"
                  placeholder="Search by symbol or company name"
                  value={portfolioSearchQuery}
                  onChange={(e) => setPortfolioSearchQuery(e.target.value)}
                  onKeyPress={(e) => e.key === 'Enter' && searchPortfolioTicker()}
                  style={{
                    flex: 1,
                    padding: '12px 16px',
                    border: `1px solid ${theme.border}`,
                    borderRadius: '8px',
                    fontSize: '14px',
                    backgroundColor: theme.surface,
                    color: theme.text,
                  }}
                />
                <button
                  onClick={searchPortfolioTicker}
                  disabled={portfolioSearching || !portfolioSearchQuery.trim()}
                  style={{
                    padding: '12px 24px',
                    backgroundColor: '#6366f1',
                    color: '#ffffff',
                    border: 'none',
                    borderRadius: '8px',
                    cursor: portfolioSearching ? 'not-allowed' : 'pointer',
                    fontSize: '14px',
                    fontWeight: '500',
                  }}
                >
                  {portfolioSearching ? 'Searching...' : 'Search'}
                </button>
              </div>
              {portfolioSearchError && (
                <div style={{ marginTop: '12px', padding: '12px', backgroundColor: '#fef2f2', borderRadius: '8px', color: theme.errorText, fontSize: '13px' }}>
                  {portfolioSearchError}
                </div>
              )}
              {!portfolioSearchError && portfolioSearchResults && portfolioSearchResults.length > 0 && (
                <div style={{ marginTop: '12px' }}>
                  <div style={{ fontSize: '13px', color: theme.textMuted, marginBottom: '8px' }}>Search results - click Add to add to portfolio</div>
                  <div style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}>
                    {portfolioSearchResults.map((result) => {
                      const symbol = (result && result.symbol) || (typeof result === 'string' ? result : '');
                      if (!symbol) return null;
                      return (
                        <div
                          key={symbol}
                          style={{
                            display: 'flex',
                            alignItems: 'center',
                            gap: '8px',
                            padding: '8px 12px',
                            backgroundColor: theme.secondaryBgAlt,
                            borderRadius: '8px',
                            border: `1px solid ${theme.border}`,
                          }}
                        >
                          <span style={{ fontWeight: '600', fontSize: '14px' }}>{symbol}</span>
                          {result.name && <span style={{ fontSize: '12px', color: theme.textMuted }}>{result.name}</span>}
                          <button
                            onClick={() => addTickerToPortfolio(symbol)}
                            style={{
                              padding: '4px 10px',
                              backgroundColor: '#10b981',
                              color: '#ffffff',
                              border: 'none',
                              borderRadius: '4px',
                              cursor: 'pointer',
                              fontSize: '12px',
                              fontWeight: '500',
                            }}
                          >
                            Add
                          </button>
                        </div>
                      );
                    })}
                  </div>
                </div>
              )}
              {!portfolioSearchError && portfolioHasSearched && !portfolioSearching && portfolioSearchResults.length === 0 && (
                <div style={{ marginTop: '12px', fontSize: '13px', color: theme.textMuted }}>No matches found. Try a symbol (e.g. AAPL) or company name.</div>
              )}
            </div>
            <div
              style={{
                padding: '20px',
                backgroundColor: theme.surface,
                border: `1px solid ${theme.border}`,
                borderRadius: '12px',
                marginBottom: '24px',
                boxShadow: '0 8px 32px rgba(0, 0, 0, 0.04)',
              }}
            >
              <div style={{ fontSize: '16px', fontWeight: '600', marginBottom: '12px' }}>Track Stock (manual)</div>
              <div style={{ fontSize: '13px', color: theme.textMuted, marginBottom: '16px' }}>
                Or enter a ticker symbol directly to track.
              </div>
              <div style={{ display: 'flex', gap: '12px' }}>
                <input
                  type="text"
                  placeholder="Enter ticker symbol (e.g., AAPL, TSLA)"
                  value={newTickerInput}
                  onChange={(e) => setNewTickerInput(e.target.value.toUpperCase())}
                  onKeyPress={(e) => e.key === 'Enter' && addTickerToWatchlist()}
                  style={{
                    flex: 1,
                    padding: '12px 16px',
                    border: `1px solid ${theme.border}`,
                    borderRadius: '8px',
                    fontSize: '14px',
                    backgroundColor: theme.surface,
                    color: theme.text,
                  }}
                />
                <button
                  onClick={addTickerToWatchlist}
                  style={{
                    padding: '12px 24px',
                    backgroundColor: '#6366f1',
                    color: '#ffffff',
                    border: 'none',
                    borderRadius: '8px',
                    cursor: 'pointer',
                    fontSize: '14px',
                    fontWeight: '500',
                  }}
                >
                  Track Stock
                </button>
              </div>
            </div>

            {Object.keys(positions || {}).length === 0 && (watchlist || []).length === 0 ? (
              <div style={{ textAlign: 'center', padding: '40px', color: theme.textMutedLight }}>No positions tracked. Add stocks above to get started!</div>
            ) : (
              <div>
                {Object.keys(positions || {}).length > 0 && (
                  <div
                    style={{
                      padding: '20px',
                      backgroundColor: theme.surface,
                      border: `1px solid ${theme.border}`,
                      borderRadius: '12px',
                      marginBottom: '24px',
                      boxShadow: '0 8px 32px rgba(0, 0, 0, 0.04)',
                    }}
                  >
                    <h3 style={{ fontSize: '18px', fontWeight: '600', marginBottom: '16px' }}>Portfolio Summary</h3>
                    {(() => {
                      const pos = positions || {};
                      const totalCost = Object.values(pos).reduce((sum, p) => sum + (p.costBasis || (p.quantity || 0) * (p.entryPrice || 0)), 0);
                      const totalValue = Object.values(pos).reduce((sum, p) => sum + (p.currentValue || (p.quantity || 0) * (p.currentPrice || p.entryPrice || 0)), 0);
                      const totalPL = totalValue - totalCost;
                      const totalPLPercent = totalCost > 0 ? ((totalPL / totalCost) * 100).toFixed(2) : 0;
                      return (
                        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '16px' }}>
                          <div>
                            <div style={{ fontSize: '12px', color: theme.textMuted, marginBottom: '4px' }}>Total Cost</div>
                            <div style={{ fontSize: '20px', fontWeight: '600' }}>${totalCost.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</div>
                          </div>
                          <div>
                            <div style={{ fontSize: '12px', color: theme.textMuted, marginBottom: '4px' }}>Current Value</div>
                            <div style={{ fontSize: '20px', fontWeight: '600' }}>${totalValue.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</div>
                          </div>
                          <div>
                            <div style={{ fontSize: '12px', color: theme.textMuted, marginBottom: '4px' }}>P&L</div>
                            <div style={{ fontSize: '20px', fontWeight: '600', color: totalPL >= 0 ? '#10b981' : '#ef4444' }}>
                              ${totalPL.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })} ({totalPLPercent}%)
                            </div>
                          </div>
                        </div>
                      );
                    })()}
                  </div>
                )}

                <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(300px, 1fr))', gap: '16px' }}>
                  {[...new Set([...(watchlist || []), ...Object.keys(positions || {})])].map((ticker) => {
                    const position = (positions || {})[ticker] || {};
                    const notes = (tickerNotes || {})[ticker] || '';
                    const costBasis = (position.quantity || 0) * (position.entryPrice || 0);
                    const currentValue = (position.quantity || 0) * (position.currentPrice || position.entryPrice || 0);
                    const pl = currentValue - costBasis;
                    const plPercent = costBasis > 0 ? ((pl / costBasis) * 100).toFixed(2) : 0;

                    return (
                      <div
                        key={ticker}
                        style={{
                          padding: '20px',
                          backgroundColor: theme.surface,
                          border: `1px solid ${theme.border}`,
                          borderRadius: '12px',
                          boxShadow: '0 8px 32px rgba(0, 0, 0, 0.04)',
                        }}
                      >
                        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '16px' }}>
                          <div style={{ fontSize: '20px', fontWeight: '600' }}>{ticker}</div>
                          <button
                            onClick={() => {
                              if (typeof window !== 'undefined' && window.confirm && window.confirm(`Remove ${ticker} from tracking?`)) {
                                const currentWatchlist = watchlist || [];
                                setWatchlist(currentWatchlist.filter((t) => t !== ticker));
                                deletePosition(ticker);
                              }
                            }}
                            style={{
                              padding: '4px 8px',
                              backgroundColor: '#ef4444',
                              color: '#ffffff',
                              border: 'none',
                              borderRadius: '4px',
                              cursor: 'pointer',
                              fontSize: '12px',
                            }}
                          >
                            Remove
                          </button>
                        </div>

                        {editingPosition === ticker ? (
                          <div>
                            <div style={{ marginBottom: '12px' }}>
                              <label style={{ display: 'block', fontSize: '12px', marginBottom: '4px' }}>Quantity</label>
                              <input
                                type="number"
                                value={position.quantity || ''}
                                onChange={(e) => updatePosition(ticker, { ...position, quantity: parseFloat(e.target.value) || 0 })}
                                style={{
                                  width: '100%',
                                  padding: '8px',
                                  border: `1px solid ${theme.border}`,
                                  borderRadius: '6px',
                                  fontSize: '14px',
                                  backgroundColor: theme.surface,
                                  color: theme.text,
                                }}
                              />
                            </div>
                            <div style={{ marginBottom: '12px' }}>
                              <label style={{ display: 'block', fontSize: '12px', marginBottom: '4px' }}>Entry Price</label>
                              <input
                                type="number"
                                step="0.01"
                                value={position.entryPrice || ''}
                                onChange={(e) => updatePosition(ticker, { ...position, entryPrice: parseFloat(e.target.value) || 0 })}
                                style={{
                                  width: '100%',
                                  padding: '8px',
                                  border: `1px solid ${theme.border}`,
                                  borderRadius: '6px',
                                  fontSize: '14px',
                                  backgroundColor: theme.surface,
                                  color: theme.text,
                                }}
                              />
                            </div>
                            <div style={{ marginBottom: '12px' }}>
                              <label style={{ display: 'block', fontSize: '12px', marginBottom: '4px' }}>Current Price</label>
                              <input
                                type="number"
                                step="0.01"
                                value={position.currentPrice || ''}
                                onChange={(e) => updatePosition(ticker, { ...position, currentPrice: parseFloat(e.target.value) || 0 })}
                                style={{
                                  width: '100%',
                                  padding: '8px',
                                  border: `1px solid ${theme.border}`,
                                  borderRadius: '6px',
                                  fontSize: '14px',
                                  backgroundColor: theme.surface,
                                  color: theme.text,
                                }}
                              />
                            </div>
                            <div style={{ marginBottom: '12px' }}>
                              <label style={{ display: 'block', fontSize: '12px', marginBottom: '4px' }}>Target Price</label>
                              <input
                                type="number"
                                step="0.01"
                                value={position.targetPrice || ''}
                                onChange={(e) => updatePosition(ticker, { ...position, targetPrice: parseFloat(e.target.value) || 0 })}
                                style={{
                                  width: '100%',
                                  padding: '8px',
                                  border: `1px solid ${theme.border}`,
                                  borderRadius: '6px',
                                  fontSize: '14px',
                                  backgroundColor: theme.surface,
                                  color: theme.text,
                                }}
                              />
                            </div>
                            <div style={{ display: 'flex', gap: '8px' }}>
                              <button
                                onClick={() => {
                                  updatePosition(ticker, {
                                    ...position,
                                    costBasis: (position.quantity || 0) * (position.entryPrice || 0),
                                    currentValue: (position.quantity || 0) * (position.currentPrice || position.entryPrice || 0),
                                  });
                                  setEditingPosition(null);
                                }}
                                style={{
                                  flex: 1,
                                  padding: '8px',
                                  backgroundColor: '#10b981',
                                  color: '#ffffff',
                                  border: 'none',
                                  borderRadius: '6px',
                                  cursor: 'pointer',
                                  fontSize: '13px',
                                  fontWeight: '500',
                                }}
                              >
                                Save
                              </button>
                              <button
                                onClick={() => setEditingPosition(null)}
                                style={{
                                  flex: 1,
                                  padding: '8px',
                                  backgroundColor: theme.secondaryBgAlt,
                                  color: theme.text,
                                  border: `1px solid ${theme.border}`,
                                  borderRadius: '6px',
                                  cursor: 'pointer',
                                  fontSize: '13px',
                                }}
                              >
                                Cancel
                              </button>
                            </div>
                          </div>
                        ) : (
                          <div>
                            {position.quantity ? (
                              <div style={{ marginBottom: '16px' }}>
                                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '8px', fontSize: '13px', marginBottom: '8px' }}>
                                  <div>
                                    <div style={{ color: theme.textMuted }}>Quantity</div>
                                    <div style={{ fontWeight: '600' }}>{position.quantity}</div>
                                  </div>
                                  <div>
                                    <div style={{ color: theme.textMuted }}>Entry</div>
                                    <div style={{ fontWeight: '600' }}>${(position.entryPrice != null && position.entryPrice !== '') ? Number(position.entryPrice).toFixed(2) : '0.00'}</div>
                                  </div>
                                  <div>
                                    <div style={{ color: theme.textMuted }}>Current</div>
                                    <div style={{ fontWeight: '600' }}>${(position.currentPrice != null && position.currentPrice !== '') ? Number(position.currentPrice).toFixed(2) : (position.entryPrice != null ? Number(position.entryPrice).toFixed(2) : '0.00')}</div>
                                  </div>
                                  <div>
                                    <div style={{ color: theme.textMuted }}>Target</div>
                                    <div style={{ fontWeight: '600' }}>${(position.targetPrice != null && position.targetPrice !== '') ? Number(position.targetPrice).toFixed(2) : 'N/A'}</div>
                                  </div>
                                </div>
                                <div
                                  style={{
                                    padding: '12px',
                                    backgroundColor: theme.secondaryBgAlt,
                                    borderRadius: '8px',
                                    marginTop: '12px',
                                  }}
                                >
                                  <div style={{ fontSize: '12px', color: theme.textMuted, marginBottom: '4px' }}>P&L</div>
                                  <div style={{ fontSize: '18px', fontWeight: '600', color: pl >= 0 ? '#10b981' : '#ef4444' }}>
                                    ${Number(pl).toFixed(2)} ({plPercent}%)
                                  </div>
                                </div>
                              </div>
                            ) : (
                              <div style={{ marginBottom: '16px', fontSize: '13px', color: theme.textMuted }}>No position data. Click "Edit Position" to add.</div>
                            )}

                            <button
                              onClick={() => setEditingPosition(ticker)}
                              style={{
                                width: '100%',
                                padding: '10px',
                                backgroundColor: '#6366f1',
                                color: '#ffffff',
                                border: 'none',
                                borderRadius: '6px',
                                cursor: 'pointer',
                                fontSize: '13px',
                                fontWeight: '500',
                                marginBottom: '12px',
                              }}
                            >
                              {position.quantity ? 'Edit Position' : 'Add Position'}
                            </button>

                            <div>
                              <div style={{ fontSize: '12px', fontWeight: '600', marginBottom: '8px' }}>Notes</div>
                              <textarea
                                value={notes}
                                onChange={(e) => setTickerNotes({ ...(tickerNotes || {}), [ticker]: e.target.value })}
                                placeholder="Add notes about this stock..."
                                style={{
                                  width: '100%',
                                  minHeight: '80px',
                                  padding: '8px',
                                  border: `1px solid ${theme.border}`,
                                  borderRadius: '6px',
                                  fontSize: '13px',
                                  backgroundColor: theme.surface,
                                  color: theme.text,
                                  resize: 'vertical',
                                  fontFamily: 'inherit',
                                }}
                              />
                            </div>
                          </div>
                        )}
                      </div>
                    );
                  })}
                </div>
              </div>
            )}
          </div>
        )}

        {activeView === 'sectors' && (
          <div>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '24px' }}>
              <h2 style={{ fontSize: '24px', fontWeight: '600' }}>Sectors</h2>
            </div>

            <div
              style={{
                padding: '20px',
                backgroundColor: theme.surface,
                border: `1px solid ${theme.border}`,
                borderRadius: '12px',
                marginBottom: '24px',
                boxShadow: '0 8px 32px rgba(0, 0, 0, 0.04)',
              }}
            >
              <div style={{ fontSize: '16px', fontWeight: '600', marginBottom: '12px' }}>Add Custom Sector</div>
              <div style={{ display: 'flex', flexWrap: 'wrap', gap: '12px', alignItems: 'flex-end' }}>
                <div style={{ flex: '1 1 200px' }}>
                  <label style={{ display: 'block', fontSize: '12px', marginBottom: '4px' }}>Sector name</label>
                  <input
                    type="text"
                    placeholder="e.g. Crypto"
                    value={newSectorName}
                    onChange={(e) => setNewSectorName(e.target.value)}
                    style={{
                      width: '100%',
                      padding: '8px 12px',
                      border: `1px solid ${theme.border}`,
                      borderRadius: '6px',
                      fontSize: '14px',
                      backgroundColor: theme.surface,
                      color: theme.text,
                    }}
                  />
                </div>
                <div style={{ flex: '1 1 240px' }}>
                  <label style={{ display: 'block', fontSize: '12px', marginBottom: '4px' }}>Keywords (comma-separated)</label>
                  <input
                    type="text"
                    placeholder="e.g. bitcoin, ethereum, crypto"
                    value={newSectorKeywords}
                    onChange={(e) => setNewSectorKeywords(e.target.value)}
                    style={{
                      width: '100%',
                      padding: '8px 12px',
                      border: `1px solid ${theme.border}`,
                      borderRadius: '6px',
                      fontSize: '14px',
                      backgroundColor: theme.surface,
                      color: theme.text,
                    }}
                  />
                </div>
                <button
                  onClick={addCustomSector}
                  style={{
                    padding: '10px 20px',
                    backgroundColor: '#6366f1',
                    color: '#ffffff',
                    border: 'none',
                    borderRadius: '8px',
                    cursor: 'pointer',
                    fontSize: '14px',
                    fontWeight: '500',
                  }}
                >
                  Add Custom Sector
                </button>
              </div>
            </div>

            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(250px, 1fr))', gap: '16px' }}>
              {[...(SECTORS || []), ...(customSectors || [])].map((sector) => (
                <div
                  key={sector.id}
                  style={{
                    padding: '20px',
                    backgroundColor: theme.surface,
                    border: `1px solid ${theme.border}`,
                    borderRadius: '12px',
                    boxShadow: '0 8px 32px rgba(0, 0, 0, 0.04)',
                  }}
                >
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'start', marginBottom: '12px' }}>
                    <div>
                      <div style={{ fontSize: '18px', fontWeight: '600', marginBottom: '4px' }}>
                        {sector.name}
                        {sector.custom && <span style={{ fontSize: '11px', color: '#6366f1', marginLeft: '8px' }}>(Custom)</span>}
                      </div>
                      <div style={{ fontSize: '12px', color: theme.textMuted }}>Keywords: {(sector.keywords || []).join(', ')}</div>
                    </div>
                    {sector.custom && (
                      <button
                        onClick={() => {
                          if (typeof window !== 'undefined' && window.confirm && window.confirm(`Delete sector "${sector.name}"?`)) {
                            deleteCustomSector(sector.id);
                          }
                        }}
                        style={{
                          padding: '4px 8px',
                          backgroundColor: '#ef4444',
                          color: '#ffffff',
                          border: 'none',
                          borderRadius: '4px',
                          cursor: 'pointer',
                          fontSize: '11px',
                        }}
                      >
                        Delete
                      </button>
                    )}
                  </div>
                  <label style={{ display: 'flex', alignItems: 'center', fontSize: '13px' }}>
                    <input
                      type="checkbox"
                      checked={(selectedSectors || []).includes(sector.id)}
                      onChange={(e) => {
                        if (e.target.checked) setSelectedSectors([...(selectedSectors || []), sector.id]);
                        else setSelectedSectors((selectedSectors || []).filter((s) => s !== sector.id));
                      }}
                      style={{ marginRight: '8px' }}
                    />
                    Active
                  </label>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>

      <style>{`
        @media print {
          body * { visibility: hidden; }
          #digest-content, #digest-content * { visibility: visible; }
          #digest-content { position: absolute; left: 0; top: 0; width: 100%; }
        }
      `}</style>

      {showEmailModal && digest && (
        <div
          style={{
            position: 'fixed',
            inset: 0,
            zIndex: 9999,
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            backgroundColor: 'rgba(0,0,0,0.5)',
          }}
          onClick={() => !emailLoading && setShowEmailModal(false)}
        >
          <div
            style={{
              padding: '24px',
              minWidth: '320px',
              maxWidth: '90vw',
              backgroundColor: theme.surface,
              color: theme.text,
              border: `1px solid ${theme.border}`,
              borderRadius: '12px',
              boxShadow: '0 20px 60px rgba(0,0,0,0.2)',
            }}
            onClick={(e) => e.stopPropagation()}
          >
            <h3 style={{ fontSize: '18px', fontWeight: '600', marginBottom: '8px' }}>Send digest to your email</h3>
            <p style={{ fontSize: '14px', color: theme.textMuted, marginBottom: '16px' }}>
              Enter your email and we'll send you today's digest (including key articles).
            </p>
            <input
              type="email"
              placeholder="you@example.com"
              value={emailInput}
              onChange={(e) => setEmailInput(e.target.value)}
              style={{
                width: '100%',
                padding: '12px 14px',
                marginBottom: '12px',
                border: `1px solid ${theme.border}`,
                borderRadius: '8px',
                fontSize: '15px',
                backgroundColor: theme.surface,
                color: theme.text,
                outline: 'none',
              }}
            />
            {emailError && (
              <p style={{ fontSize: '13px', color: theme.errorText, marginBottom: '12px' }}>{emailError}</p>
            )}
            <div style={{ display: 'flex', gap: '12px', justifyContent: 'flex-end' }}>
              <button
                type="button"
                onClick={() => !emailLoading && setShowEmailModal(false)}
                style={{
                  padding: '10px 18px',
                  backgroundColor: theme.secondaryBgAlt,
                  color: theme.text,
                  border: `1px solid ${theme.border}`,
                  borderRadius: '8px',
                  cursor: emailLoading ? 'not-allowed' : 'pointer',
                  fontSize: '14px',
                }}
              >
                Cancel
              </button>
              <button
                type="button"
                onClick={sendDigestEmail}
                disabled={emailLoading}
                style={{
                  padding: '10px 18px',
                  backgroundColor: '#6366f1',
                  color: '#ffffff',
                  border: 'none',
                  borderRadius: '8px',
                  cursor: emailLoading ? 'not-allowed' : 'pointer',
                  fontSize: '14px',
                  fontWeight: '500',
                }}
              >
                {emailLoading ? 'Sending...' : 'Send'}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
    </div>
  );
}

export default FinancialCommandCenter;

import React, { useState, useEffect, useMemo, useCallback, useRef } from 'react';

function NewsStockSocialTracker() {
  const [tailwindLoaded, setTailwindLoaded] = useState(false);
  
  // Tab state
  const [activeTab, setActiveTab] = useState('news');
  
  // News state
  const [newsCategory, setNewsCategory] = useState('general');
  const [newsSearchQuery, setNewsSearchQuery] = useState('');
  const [newsArticles, setNewsArticles] = useState([]);
  const [newsLoading, setNewsLoading] = useState(false);
  const [selectedArticle, setSelectedArticle] = useState(null);
  const [aiSummary, setAiSummary] = useState('');
  const [summaryLoading, setSummaryLoading] = useState(false);
  
  // Stock state
  const [stockSearch, setStockSearch] = useState('');
  const [trackedSymbols, setTrackedSymbols] = useStorage('tracked-symbols', []);
  const [stockResults, setStockResults] = useState([]);
  const [stockLoading, setStockLoading] = useState(false);
  const [stockNotes, setStockNotes] = useStorage('stock-notes', {});
  const [editingNote, setEditingNote] = useState(null);
  
  // Social state
  const [socialPlatform, setSocialPlatform] = useState('linkedin');
  const [linkedinSearch, setLinkedinSearch] = useState('');
  const [linkedinProfiles, setLinkedinProfiles] = useState([]);
  const [youtubeSearch, setYoutubeSearch] = useState('');
  const [youtubeVideos, setYoutubeVideos] = useState([]);
  const [socialLoading, setSocialLoading] = useState(false);

  useEffect(() => {
    // Load Tailwind CSS
    if (!document.getElementById('tailwind-script')) {
      const tailwindScript = document.createElement('script');
      tailwindScript.id = 'tailwind-script';
      tailwindScript.src = 'https://cdn.tailwindcss.com';
      tailwindScript.onload = () => {
        setTimeout(() => setTailwindLoaded(true), 100);
      };
      document.head.appendChild(tailwindScript);
    } else {
      setTailwindLoaded(true);
    }
    
    // Apply white background for scrollable content
    document.body.style.background = '#ffffff';
    document.documentElement.style.minHeight = '100%';
    return () => {
      document.body.style.background = '';
      document.documentElement.style.minHeight = '';
    };
  }, []);

  // Fetch news on category change or search
  useEffect(() => {
    if (tailwindLoaded && activeTab === 'news') {
      if (newsSearchQuery.trim()) {
        searchNews();
      } else {
        fetchNews();
      }
    }
  }, [newsCategory, tailwindLoaded, activeTab]);

  const fetchNews = async () => {
    setNewsLoading(true);
    setSelectedArticle(null);
    setAiSummary('');
    try {
      const response = await miyagiAPI.post('/news-top-headlines', {
        category: newsCategory,
        pageSize: 15
      });
      if (response.success) {
        setNewsArticles(response.data.articles || []);
      }
    } catch (error) {
      console.error('Error fetching news:', error);
    } finally {
      setNewsLoading(false);
    }
  };

  const searchNews = async () => {
    if (!newsSearchQuery.trim()) {
      fetchNews();
      return;
    }
    
    setNewsLoading(true);
    setSelectedArticle(null);
    setAiSummary('');
    try {
      const response = await miyagiAPI.post('/news-search', {
        q: newsSearchQuery,
        pageSize: 15,
        sortBy: 'publishedAt'
      });
      if (response.success) {
        setNewsArticles(response.data.articles || []);
      }
    } catch (error) {
      console.error('Error searching news:', error);
    } finally {
      setNewsLoading(false);
    }
  };

  const generateSummary = async (article) => {
    setSelectedArticle(article);
    setSummaryLoading(true);
    setAiSummary('');
    
    try {
      const prompt = `Summarize this news article in 3-4 bullet points, focusing on key facts and implications:\n\nTitle: ${article.title}\n\nContent: ${article.description || article.content || 'No content available'}`;
      
      const response = await miyagiAPI.post('/generate-text', {
        prompt: prompt,
        provider: 'openai',
        model: 'gpt-4o-mini',
        max_tokens: 200
      });
      
      if (response.success) {
        setAiSummary(response.data.text);
      }
    } catch (error) {
      console.error('Error generating summary:', error);
      setAiSummary('Failed to generate summary. Please try again.');
    } finally {
      setSummaryLoading(false);
    }
  };

  const searchStocks = async () => {
    if (!stockSearch.trim()) return;
    
    setStockLoading(true);
    try {
      const response = await miyagiAPI.post('/search-stocks', {
        term: stockSearch
      });
      if (response.success) {
        setStockResults(response.data.symbols || []);
      }
    } catch (error) {
      console.error('Error searching stocks:', error);
    } finally {
      setStockLoading(false);
    }
  };

  const addSymbol = (symbol) => {
    if (!trackedSymbols.find(s => s.symbol === symbol.symbol)) {
      setTrackedSymbols(prev => [...prev, symbol]);
    }
  };

  const removeSymbol = (symbolToRemove) => {
    setTrackedSymbols(prev => prev.filter(s => s.symbol !== symbolToRemove));
  };

  const searchLinkedIn = async () => {
    if (!linkedinSearch.trim()) return;
    
    setSocialLoading(true);
    try {
      const response = await miyagiAPI.post('/linkedin-search-profiles', {
        name: linkedinSearch
      });
      if (response.success) {
        setLinkedinProfiles(response.data.profiles || []);
      }
    } catch (error) {
      console.error('Error searching LinkedIn:', error);
    } finally {
      setSocialLoading(false);
    }
  };

  const searchYouTube = async () => {
    if (!youtubeSearch.trim()) return;
    
    setSocialLoading(true);
    try {
      const response = await miyagiAPI.post('/youtube-search', {
        query: youtubeSearch,
        maxResults: 10
      });
      if (response.success) {
        setYoutubeVideos(response.data.videos || []);
      }
    } catch (error) {
      console.error('Error searching YouTube:', error);
    } finally {
      setSocialLoading(false);
    }
  };

  const saveStockNote = (symbol, note) => {
    setStockNotes(prev => ({
      ...prev,
      [symbol]: note
    }));
    setEditingNote(null);
  };

  const formatDate = (dateString) => {
    const date = new Date(dateString);
    const now = new Date();
    const diffMs = now - date;
    const diffMins = Math.floor(diffMs / 60000);
    const diffHours = Math.floor(diffMs / 3600000);
    const diffDays = Math.floor(diffMs / 86400000);
    
    if (diffMins < 60) return `${diffMins}m ago`;
    if (diffHours < 24) return `${diffHours}h ago`;
    if (diffDays < 7) return `${diffDays}d ago`;
    return date.toLocaleDateString();
  };

  if (!tailwindLoaded) {
    return <div style={{ padding: '20px', textAlign: 'center' }}>Loading...</div>;
  }

  return (
    <div style={{ fontFamily: '-apple-system, BlinkMacSystemFont, "Inter", "Helvetica Neue", Arial, sans-serif' }}>
      {/* Header */}
      <div style={{ 
        padding: '32px 40px',
        borderBottom: '1px solid #f0f0f0'
      }}>
        <h1 style={{ 
          fontSize: '28px', 
          fontWeight: '600',
          margin: 0,
          color: '#000000',
          letterSpacing: '-0.5px'
        }}>
          News + Stock + Social Tracker
        </h1>
        <p style={{
          margin: '8px 0 0 0',
          fontSize: '14px',
          color: '#666666',
          fontWeight: '400'
        }}>
          Track news, markets, and social profiles in one place
        </p>
      </div>

      {/* Tabs */}
      <div style={{
        padding: '0 40px',
        borderBottom: '1px solid #f0f0f0',
        display: 'flex',
        gap: '32px'
      }}>
        {['news', 'stocks', 'social'].map(tab => (
          <button
            key={tab}
            onClick={() => setActiveTab(tab)}
            style={{
              padding: '16px 0',
              border: 'none',
              background: 'none',
              fontSize: '14px',
              fontWeight: activeTab === tab ? '600' : '400',
              color: activeTab === tab ? '#000000' : '#666666',
              cursor: 'pointer',
              borderBottom: activeTab === tab ? '2px solid #6366f1' : '2px solid transparent',
              transition: 'all 0.2s',
              textTransform: 'capitalize'
            }}
          >
            {tab}
          </button>
        ))}
      </div>

      {/* Content */}
      <div style={{ padding: '40px' }}>
        {/* News Tab */}
        {activeTab === 'news' && (
          <div>
            {/* Search Bar */}
            <div style={{ marginBottom: '24px' }}>
              <label style={{ 
                display: 'block',
                fontSize: '13px',
                fontWeight: '500',
                color: '#000000',
                marginBottom: '12px',
                textTransform: 'uppercase',
                letterSpacing: '0.5px'
              }}>
                Search News
              </label>
              <div style={{ display: 'flex', gap: '12px' }}>
                <input
                  type="text"
                  value={newsSearchQuery}
                  onChange={(e) => setNewsSearchQuery(e.target.value)}
                  onKeyPress={(e) => e.key === 'Enter' && searchNews()}
                  placeholder="Search for specific topics, companies, or keywords..."
                  style={{
                    flex: 1,
                    padding: '14px 20px',
                    border: '1px solid #f0f0f0',
                    borderRadius: '10px',
                    fontSize: '14px',
                    outline: 'none',
                    transition: 'all 0.2s'
                  }}
                  onFocus={(e) => e.target.style.borderColor = '#6366f1'}
                  onBlur={(e) => e.target.style.borderColor = '#f0f0f0'}
                />
                <button
                  onClick={searchNews}
                  style={{
                    padding: '14px 24px',
                    background: '#6366f1',
                    color: '#ffffff',
                    border: 'none',
                    borderRadius: '10px',
                    fontSize: '14px',
                    fontWeight: '600',
                    cursor: 'pointer',
                    transition: 'all 0.2s'
                  }}
                >
                  Search
                </button>
                {newsSearchQuery && (
                  <button
                    onClick={() => {
                      setNewsSearchQuery('');
                      fetchNews();
                    }}
                    style={{
                      padding: '14px 20px',
                      background: '#f0f0f0',
                      color: '#666666',
                      border: 'none',
                      borderRadius: '10px',
                      fontSize: '14px',
                      fontWeight: '600',
                      cursor: 'pointer',
                      transition: 'all 0.2s'
                    }}
                  >
                    Clear
                  </button>
                )}
              </div>
            </div>

            {/* Category Filter */}
            {!newsSearchQuery && (
              <div style={{ marginBottom: '32px' }}>
                <label style={{ 
                  display: 'block',
                  fontSize: '13px',
                  fontWeight: '500',
                  color: '#000000',
                  marginBottom: '12px',
                  textTransform: 'uppercase',
                  letterSpacing: '0.5px'
                }}>
                  Category
                </label>
                <div style={{ display: 'flex', gap: '12px', flexWrap: 'wrap' }}>
                  {['general', 'business', 'technology', 'sports', 'entertainment', 'health', 'science'].map(cat => (
                    <button
                      key={cat}
                      onClick={() => setNewsCategory(cat)}
                      style={{
                        padding: '10px 20px',
                        border: newsCategory === cat ? '1px solid #6366f1' : '1px solid #f0f0f0',
                        background: newsCategory === cat ? '#6366f1' : '#ffffff',
                        color: newsCategory === cat ? '#ffffff' : '#666666',
                        borderRadius: '8px',
                        fontSize: '13px',
                        fontWeight: '500',
                        cursor: 'pointer',
                        transition: 'all 0.2s',
                        textTransform: 'capitalize'
                      }}
                    >
                      {cat}
                    </button>
                  ))}
                </div>
              </div>
            )}

            {/* News Articles */}
            {newsLoading ? (
              <div style={{ textAlign: 'center', padding: '60px', color: '#999999' }}>
                Loading news...
              </div>
            ) : (
              <div style={{ display: 'flex', flexDirection: 'column', gap: '20px' }}>
                {newsArticles.map((article, idx) => (
                  <div
                    key={idx}
                    style={{
                      padding: '24px',
                      background: '#ffffff',
                      border: selectedArticle === article ? '1px solid #6366f1' : '1px solid #f0f0f0',
                      borderRadius: '12px',
                      boxShadow: '0 4px 24px rgba(0, 0, 0, 0.04)',
                      transition: 'all 0.2s'
                    }}
                  >
                    <div style={{ display: 'flex', gap: '20px', marginBottom: '16px' }}>
                      {article.urlToImage && (
                        <img 
                          src={article.urlToImage} 
                          alt=""
                          style={{
                            width: '120px',
                            height: '80px',
                            objectFit: 'cover',
                            borderRadius: '8px',
                            flexShrink: 0
                          }}
                        />
                      )}
                      <div style={{ flex: 1 }}>
                        <a
                          href={article.url}
                          target="_blank"
                          rel="noopener noreferrer"
                          style={{
                            display: 'block',
                            textDecoration: 'none',
                            marginBottom: '8px'
                          }}
                        >
                          <h3 style={{
                            margin: '0 0 8px 0',
                            fontSize: '16px',
                            fontWeight: '600',
                            color: '#000000',
                            lineHeight: '1.4'
                          }}>
                            {article.title}
                          </h3>
                        </a>
                        <p style={{
                          margin: '0 0 12px 0',
                          fontSize: '14px',
                          color: '#666666',
                          lineHeight: '1.5'
                        }}>
                          {article.description}
                        </p>
                        <div style={{
                          display: 'flex',
                          gap: '16px',
                          fontSize: '12px',
                          color: '#999999',
                          alignItems: 'center'
                        }}>
                          <span>{article.source.name}</span>
                          <span>•</span>
                          <span>{formatDate(article.publishedAt)}</span>
                          <button
                            onClick={(e) => {
                              e.stopPropagation();
                              generateSummary(article);
                            }}
                            style={{
                              marginLeft: 'auto',
                              padding: '6px 14px',
                              background: selectedArticle === article ? '#6366f1' : '#f0f0f0',
                              color: selectedArticle === article ? '#ffffff' : '#666666',
                              border: 'none',
                              borderRadius: '6px',
                              fontSize: '12px',
                              fontWeight: '600',
                              cursor: 'pointer',
                              transition: 'all 0.2s'
                            }}
                          >
                            {selectedArticle === article ? '✓ AI Summary' : '✨ AI Summary'}
                          </button>
                        </div>
                      </div>
                    </div>
                    
                    {/* AI Summary Section */}
                    {selectedArticle === article && (
                      <div style={{
                        padding: '20px',
                        background: '#f8f9ff',
                        borderRadius: '8px',
                        border: '1px solid #e0e7ff'
                      }}>
                        <div style={{
                          fontSize: '12px',
                          fontWeight: '600',
                          color: '#6366f1',
                          marginBottom: '12px',
                          textTransform: 'uppercase',
                          letterSpacing: '0.5px'
                        }}>
                          AI-Generated Summary
                        </div>
                        {summaryLoading ? (
                          <div style={{ color: '#666666', fontSize: '14px' }}>
                            Generating summary...
                          </div>
                        ) : aiSummary ? (
                          <div style={{
                            fontSize: '14px',
                            color: '#333333',
                            lineHeight: '1.6',
                            whiteSpace: 'pre-wrap'
                          }}>
                            {aiSummary}
                          </div>
                        ) : null}
                      </div>
                    )}
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        {/* Stocks Tab */}
        {activeTab === 'stocks' && (
          <div>
            {/* Search */}
            <div style={{ marginBottom: '32px' }}>
              <label style={{ 
                display: 'block',
                fontSize: '13px',
                fontWeight: '500',
                color: '#000000',
                marginBottom: '12px',
                textTransform: 'uppercase',
                letterSpacing: '0.5px'
              }}>
                Search Stocks
              </label>
              <div style={{ display: 'flex', gap: '12px' }}>
                <input
                  type="text"
                  value={stockSearch}
                  onChange={(e) => setStockSearch(e.target.value)}
                  onKeyPress={(e) => e.key === 'Enter' && searchStocks()}
                  placeholder="Search by company name or symbol..."
                  style={{
                    flex: 1,
                    padding: '14px 20px',
                    border: '1px solid #f0f0f0',
                    borderRadius: '10px',
                    fontSize: '14px',
                    outline: 'none',
                    transition: 'all 0.2s'
                  }}
                  onFocus={(e) => e.target.style.borderColor = '#6366f1'}
                  onBlur={(e) => e.target.style.borderColor = '#f0f0f0'}
                />
                <button
                  onClick={searchStocks}
                  disabled={stockLoading}
                  style={{
                    padding: '14px 32px',
                    background: '#6366f1',
                    color: '#ffffff',
                    border: 'none',
                    borderRadius: '10px',
                    fontSize: '14px',
                    fontWeight: '600',
                    cursor: stockLoading ? 'default' : 'pointer',
                    opacity: stockLoading ? 0.6 : 1,
                    transition: 'all 0.2s'
                  }}
                >
                  {stockLoading ? 'Searching...' : 'Search'}
                </button>
              </div>
            </div>

            {/* Search Results */}
            {stockResults.length > 0 && (
              <div style={{ marginBottom: '40px' }}>
                <h3 style={{
                  fontSize: '13px',
                  fontWeight: '500',
                  color: '#000000',
                  marginBottom: '16px',
                  textTransform: 'uppercase',
                  letterSpacing: '0.5px'
                }}>
                  Search Results
                </h3>
                <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
                  {stockResults.slice(0, 5).map((symbol, idx) => (
                    <div
                      key={idx}
                      style={{
                        display: 'flex',
                        justifyContent: 'space-between',
                        alignItems: 'center',
                        padding: '16px 20px',
                        background: '#ffffff',
                        border: '1px solid #f0f0f0',
                        borderRadius: '10px'
                      }}
                    >
                      <div>
                        <div style={{ 
                          fontSize: '15px', 
                          fontWeight: '600',
                          color: '#000000',
                          marginBottom: '4px'
                        }}>
                          {symbol.symbol}
                        </div>
                        <div style={{ 
                          fontSize: '13px', 
                          color: '#666666'
                        }}>
                          {symbol.name}
                        </div>
                      </div>
                      <button
                        onClick={() => addSymbol(symbol)}
                        style={{
                          padding: '8px 16px',
                          background: '#6366f1',
                          color: '#ffffff',
                          border: 'none',
                          borderRadius: '6px',
                          fontSize: '12px',
                          fontWeight: '600',
                          cursor: 'pointer',
                          transition: 'all 0.2s'
                        }}
                      >
                        Track
                      </button>
                    </div>
                  ))}
                </div>
              </div>
            )}

            {/* Tracked Symbols */}
            <div>
              <h3 style={{
                fontSize: '13px',
                fontWeight: '500',
                color: '#000000',
                marginBottom: '16px',
                textTransform: 'uppercase',
                letterSpacing: '0.5px'
              }}>
                Tracked Symbols ({trackedSymbols.length})
              </h3>
              {trackedSymbols.length === 0 ? (
                <div style={{
                  padding: '60px 20px',
                  textAlign: 'center',
                  color: '#999999',
                  border: '1px solid #f0f0f0',
                  borderRadius: '12px',
                  background: '#fafafa'
                }}>
                  No symbols tracked yet. Search and add stocks to track them.
                </div>
              ) : (
                <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(280px, 1fr))', gap: '16px' }}>
                  {trackedSymbols.map((symbol, idx) => (
                    <div
                      key={idx}
                      style={{
                        padding: '20px',
                        background: '#ffffff',
                        border: '1px solid #f0f0f0',
                        borderRadius: '12px',
                        boxShadow: '0 4px 24px rgba(0, 0, 0, 0.04)',
                        position: 'relative'
                      }}
                    >
                      <button
                        onClick={() => removeSymbol(symbol.symbol)}
                        style={{
                          position: 'absolute',
                          top: '12px',
                          right: '12px',
                          width: '24px',
                          height: '24px',
                          border: 'none',
                          background: '#f0f0f0',
                          borderRadius: '6px',
                          cursor: 'pointer',
                          fontSize: '14px',
                          color: '#666666',
                          display: 'flex',
                          alignItems: 'center',
                          justifyContent: 'center'
                        }}
                      >
                        ×
                      </button>
                      <div style={{
                        fontSize: '20px',
                        fontWeight: '700',
                        color: '#000000',
                        marginBottom: '8px',
                        paddingRight: '30px'
                      }}>
                        {symbol.symbol}
                      </div>
                      <div style={{
                        fontSize: '13px',
                        color: '#666666',
                        marginBottom: '8px'
                      }}>
                        {symbol.name}
                      </div>
                      <div style={{
                        fontSize: '11px',
                        color: '#999999',
                        marginBottom: '16px'
                      }}>
                        {symbol.region} • {symbol.currency}
                      </div>
                      
                      {/* Notes Section */}
                      {editingNote === symbol.symbol ? (
                        <div>
                          <textarea
                            defaultValue={stockNotes[symbol.symbol] || ''}
                            placeholder="Add notes about this stock..."
                            style={{
                              width: '100%',
                              padding: '10px',
                              border: '1px solid #e0e7ff',
                              borderRadius: '6px',
                              fontSize: '12px',
                              fontFamily: 'inherit',
                              resize: 'vertical',
                              minHeight: '60px',
                              outline: 'none',
                              marginBottom: '8px'
                            }}
                            onKeyDown={(e) => {
                              if (e.key === 'Enter' && e.metaKey) {
                                saveStockNote(symbol.symbol, e.target.value);
                              }
                              if (e.key === 'Escape') {
                                setEditingNote(null);
                              }
                            }}
                            autoFocus
                          />
                          <div style={{ display: 'flex', gap: '8px' }}>
                            <button
                              onClick={(e) => {
                                const textarea = e.target.parentElement.previousElementSibling;
                                saveStockNote(symbol.symbol, textarea.value);
                              }}
                              style={{
                                padding: '6px 12px',
                                background: '#6366f1',
                                color: '#ffffff',
                                border: 'none',
                                borderRadius: '6px',
                                fontSize: '11px',
                                fontWeight: '600',
                                cursor: 'pointer',
                                flex: 1
                              }}
                            >
                              Save
                            </button>
                            <button
                              onClick={() => setEditingNote(null)}
                              style={{
                                padding: '6px 12px',
                                background: '#f0f0f0',
                                color: '#666666',
                                border: 'none',
                                borderRadius: '6px',
                                fontSize: '11px',
                                fontWeight: '600',
                                cursor: 'pointer'
                              }}
                            >
                              Cancel
                            </button>
                          </div>
                        </div>
                      ) : (
                        <div>
                          {stockNotes[symbol.symbol] ? (
                            <div
                              onClick={() => setEditingNote(symbol.symbol)}
                              style={{
                                padding: '10px',
                                background: '#f8f9ff',
                                borderRadius: '6px',
                                fontSize: '12px',
                                color: '#333333',
                                lineHeight: '1.5',
                                cursor: 'pointer',
                                marginBottom: '8px',
                                border: '1px solid #e0e7ff'
                              }}
                            >
                              {stockNotes[symbol.symbol]}
                            </div>
                          ) : (
                            <button
                              onClick={() => setEditingNote(symbol.symbol)}
                              style={{
                                width: '100%',
                                padding: '8px',
                                background: '#fafafa',
                                color: '#999999',
                                border: '1px dashed #e0e0e0',
                                borderRadius: '6px',
                                fontSize: '11px',
                                fontWeight: '500',
                                cursor: 'pointer',
                                transition: 'all 0.2s'
                              }}
                            >
                              + Add Notes
                            </button>
                          )}
                        </div>
                      )}
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>
        )}

        {/* Social Tab */}
        {activeTab === 'social' && (
          <div>
            {/* Platform Selector */}
            <div style={{ marginBottom: '32px' }}>
              <label style={{ 
                display: 'block',
                fontSize: '13px',
                fontWeight: '500',
                color: '#000000',
                marginBottom: '12px',
                textTransform: 'uppercase',
                letterSpacing: '0.5px'
              }}>
                Platform
              </label>
              <div style={{ display: 'flex', gap: '12px' }}>
                {['linkedin', 'tiktok', 'youtube'].map(platform => (
                  <button
                    key={platform}
                    onClick={() => setSocialPlatform(platform)}
                    style={{
                      padding: '10px 20px',
                      border: socialPlatform === platform ? '1px solid #6366f1' : '1px solid #f0f0f0',
                      background: socialPlatform === platform ? '#6366f1' : '#ffffff',
                      color: socialPlatform === platform ? '#ffffff' : '#666666',
                      borderRadius: '8px',
                      fontSize: '13px',
                      fontWeight: '500',
                      cursor: 'pointer',
                      transition: 'all 0.2s',
                      textTransform: 'capitalize'
                    }}
                  >
                    {platform}
                  </button>
                ))}
              </div>
            </div>

            {/* LinkedIn Search */}
            {socialPlatform === 'linkedin' && (
              <div>
                <div style={{ marginBottom: '32px' }}>
                  <label style={{ 
                    display: 'block',
                    fontSize: '13px',
                    fontWeight: '500',
                    color: '#000000',
                    marginBottom: '12px',
                    textTransform: 'uppercase',
                    letterSpacing: '0.5px'
                  }}>
                    Search LinkedIn Profiles
                  </label>
                  <div style={{ display: 'flex', gap: '12px' }}>
                    <input
                      type="text"
                      value={linkedinSearch}
                      onChange={(e) => setLinkedinSearch(e.target.value)}
                      onKeyPress={(e) => e.key === 'Enter' && searchLinkedIn()}
                      placeholder="Search by name..."
                      style={{
                        flex: 1,
                        padding: '14px 20px',
                        border: '1px solid #f0f0f0',
                        borderRadius: '10px',
                        fontSize: '14px',
                        outline: 'none',
                        transition: 'all 0.2s'
                      }}
                      onFocus={(e) => e.target.style.borderColor = '#6366f1'}
                      onBlur={(e) => e.target.style.borderColor = '#f0f0f0'}
                    />
                    <button
                      onClick={searchLinkedIn}
                      disabled={socialLoading}
                      style={{
                        padding: '14px 32px',
                        background: '#6366f1',
                        color: '#ffffff',
                        border: 'none',
                        borderRadius: '10px',
                        fontSize: '14px',
                        fontWeight: '600',
                        cursor: socialLoading ? 'default' : 'pointer',
                        opacity: socialLoading ? 0.6 : 1,
                        transition: 'all 0.2s'
                      }}
                    >
                      {socialLoading ? 'Searching...' : 'Search'}
                    </button>
                  </div>
                </div>

                {/* LinkedIn Results */}
                {linkedinProfiles.length > 0 && (
                  <div>
                    <h3 style={{
                      fontSize: '13px',
                      fontWeight: '500',
                      color: '#000000',
                      marginBottom: '16px',
                      textTransform: 'uppercase',
                      letterSpacing: '0.5px'
                    }}>
                      Search Results ({linkedinProfiles.length})
                    </h3>
                    <div style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
                      {linkedinProfiles.map((profile, idx) => (
                        <a
                          key={idx}
                          href={profile.link}
                          target="_blank"
                          rel="noopener noreferrer"
                          style={{
                            display: 'block',
                            padding: '20px',
                            background: '#ffffff',
                            border: '1px solid #f0f0f0',
                            borderRadius: '12px',
                            textDecoration: 'none',
                            boxShadow: '0 4px 24px rgba(0, 0, 0, 0.04)',
                            transition: 'all 0.2s'
                          }}
                          onMouseOver={(e) => {
                            e.currentTarget.style.boxShadow = '0 8px 32px rgba(0, 0, 0, 0.08)';
                            e.currentTarget.style.transform = 'translateY(-2px)';
                          }}
                          onMouseOut={(e) => {
                            e.currentTarget.style.boxShadow = '0 4px 24px rgba(0, 0, 0, 0.04)';
                            e.currentTarget.style.transform = 'translateY(0)';
                          }}
                        >
                          <div style={{
                            fontSize: '16px',
                            fontWeight: '600',
                            color: '#000000',
                            marginBottom: '6px'
                          }}>
                            {profile.name}
                          </div>
                          <div style={{
                            fontSize: '14px',
                            color: '#666666',
                            marginBottom: '6px'
                          }}>
                            {profile.headline}
                          </div>
                          <div style={{
                            fontSize: '12px',
                            color: '#999999'
                          }}>
                            {profile.location}
                          </div>
                        </a>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            )}

            {/* YouTube Search */}
            {socialPlatform === 'youtube' && (
              <div>
                <div style={{ marginBottom: '32px' }}>
                  <label style={{ 
                    display: 'block',
                    fontSize: '13px',
                    fontWeight: '500',
                    color: '#000000',
                    marginBottom: '12px',
                    textTransform: 'uppercase',
                    letterSpacing: '0.5px'
                  }}>
                    Search YouTube Videos
                  </label>
                  <div style={{ display: 'flex', gap: '12px' }}>
                    <input
                      type="text"
                      value={youtubeSearch}
                      onChange={(e) => setYoutubeSearch(e.target.value)}
                      onKeyPress={(e) => e.key === 'Enter' && searchYouTube()}
                      placeholder="Search for videos, channels, or topics..."
                      style={{
                        flex: 1,
                        padding: '14px 20px',
                        border: '1px solid #f0f0f0',
                        borderRadius: '10px',
                        fontSize: '14px',
                        outline: 'none',
                        transition: 'all 0.2s'
                      }}
                      onFocus={(e) => e.target.style.borderColor = '#6366f1'}
                      onBlur={(e) => e.target.style.borderColor = '#f0f0f0'}
                    />
                    <button
                      onClick={searchYouTube}
                      disabled={socialLoading}
                      style={{
                        padding: '14px 32px',
                        background: '#6366f1',
                        color: '#ffffff',
                        border: 'none',
                        borderRadius: '10px',
                        fontSize: '14px',
                        fontWeight: '600',
                        cursor: socialLoading ? 'default' : 'pointer',
                        opacity: socialLoading ? 0.6 : 1,
                        transition: 'all 0.2s'
                      }}
                    >
                      {socialLoading ? 'Searching...' : 'Search'}
                    </button>
                  </div>
                </div>

                {/* YouTube Results */}
                {youtubeVideos.length > 0 && (
                  <div>
                    <h3 style={{
                      fontSize: '13px',
                      fontWeight: '500',
                      color: '#000000',
                      marginBottom: '16px',
                      textTransform: 'uppercase',
                      letterSpacing: '0.5px'
                    }}>
                      Search Results ({youtubeVideos.length})
                    </h3>
                    <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(320px, 1fr))', gap: '20px' }}>
                      {youtubeVideos.map((video, idx) => (
                        <a
                          key={idx}
                          href={`https://www.youtube.com/watch?v=${video.videoId}`}
                          target="_blank"
                          rel="noopener noreferrer"
                          style={{
                            display: 'block',
                            background: '#ffffff',
                            border: '1px solid #f0f0f0',
                            borderRadius: '12px',
                            overflow: 'hidden',
                            textDecoration: 'none',
                            boxShadow: '0 4px 24px rgba(0, 0, 0, 0.04)',
                            transition: 'all 0.2s'
                          }}
                          onMouseOver={(e) => {
                            e.currentTarget.style.boxShadow = '0 8px 32px rgba(0, 0, 0, 0.08)';
                            e.currentTarget.style.transform = 'translateY(-2px)';
                          }}
                          onMouseOut={(e) => {
                            e.currentTarget.style.boxShadow = '0 4px 24px rgba(0, 0, 0, 0.04)';
                            e.currentTarget.style.transform = 'translateY(0)';
                          }}
                        >
                          {video.thumbnail && (
                            <img
                              src={video.thumbnail}
                              alt={video.title}
                              style={{
                                width: '100%',
                                height: '180px',
                                objectFit: 'cover'
                              }}
                            />
                          )}
                          <div style={{ padding: '16px' }}>
                            <h4 style={{
                              margin: '0 0 8px 0',
                              fontSize: '14px',
                              fontWeight: '600',
                              color: '#000000',
                              lineHeight: '1.4',
                              display: '-webkit-box',
                              WebkitLineClamp: 2,
                              WebkitBoxOrient: 'vertical',
                              overflow: 'hidden'
                            }}>
                              {video.title}
                            </h4>
                            <div style={{
                              fontSize: '12px',
                              color: '#666666',
                              marginBottom: '8px'
                            }}>
                              {video.channelTitle}
                            </div>
                            <div style={{
                              fontSize: '11px',
                              color: '#999999'
                            }}>
                              {video.publishedAt && new Date(video.publishedAt).toLocaleDateString()}
                            </div>
                          </div>
                        </a>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            )}

            {/* TikTok Placeholder */}
            {socialPlatform === 'tiktok' && (
              <div style={{
                padding: '60px 20px',
                textAlign: 'center',
                color: '#999999',
                border: '1px solid #f0f0f0',
                borderRadius: '12px',
                background: '#fafafa'
              }}>
                TikTok integration: View profile info and scheduled posts
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
}

export default NewsStockSocialTracker;

import React, { useState, useCallback, useMemo, useEffect, useRef } from 'react';
import SlideThumbnails from './components/SlideThumbnails';
import SlideEditor from './components/SlideEditor';
import SlidePresenter from './components/SlidePresenter';
import HeaderBar from './components/HeaderBar';
import { exportSlidesToHTML, exportSlidesToPDF } from './utils/slideUtils';
import { initializeDefaults } from './utils/defaults';

/**
 * Slide Deck Widget
 * 
 * A clean, modern slide deck editor using file-based storage.
 * Each slide is stored as an HTML file that can be directly edited.
 * 
 * File Structure:
 * files/slides/
 * ├── config.json           # { currentDeckId, deckOrder }
 * └── {deckId}/
 *     ├── deck.json         # { title, currentSlideIndex, slideOrder }
 *     └── {slideId}.html    # Slide HTML content
 */

function generateId(prefix = 'id') {
  return `${prefix}-${Date.now()}-${Math.random().toString(36).substr(2, 6)}`;
}

function SlideDeckWidget() {
  const files = useFiles('slides/');
  
  const [isPresenting, setIsPresenting] = useState(false);
  const [showDeckSidebar, setShowDeckSidebar] = useState(false);
  const initRef = useRef(false);

  // Read config
  const config = useMemo(() => {
    const raw = files.read('config.json');
    if (!raw) return { currentDeckId: null, deckOrder: [] };
    try {
      return typeof raw === 'string' ? JSON.parse(raw) : raw;
    } catch {
      return { currentDeckId: null, deckOrder: [] };
    }
  }, [files]);

  const currentDeckId = config.currentDeckId;
  const deckOrder = config.deckOrder || [];

  const writeConfig = useCallback((updates) => {
    const newConfig = { ...config, ...updates };
    files.write('config.json', JSON.stringify(newConfig, null, 2));
  }, [files, config]);

  // Read current deck
  const currentDeckMeta = useMemo(() => {
    if (!currentDeckId) return null;
    const raw = files.read(`${currentDeckId}/deck.json`);
    if (!raw) return null;
    try {
      return typeof raw === 'string' ? JSON.parse(raw) : raw;
    } catch {
      return null;
    }
  }, [files, currentDeckId]);

  const writeDeckMeta = useCallback((deckId, updates) => {
    const raw = files.read(`${deckId}/deck.json`);
    let current = {};
    if (raw) {
      try { current = typeof raw === 'string' ? JSON.parse(raw) : raw; } catch {}
    }
    files.write(`${deckId}/deck.json`, JSON.stringify({ ...current, ...updates }, null, 2));
  }, [files]);

  // Build slides array
  const slides = useMemo(() => {
    if (!currentDeckId || !currentDeckMeta?.slideOrder) return [];
    return currentDeckMeta.slideOrder.map(slideId => ({
      id: slideId,
      content: files.read(`${currentDeckId}/${slideId}.html`) || ''
    }));
  }, [files, currentDeckId, currentDeckMeta]);

  const currentSlideIndex = currentDeckMeta?.currentSlideIndex || 0;
  const presentationTitle = currentDeckMeta?.title || 'Untitled';

  // Get ordered decks for sidebar
  const orderedDecks = useMemo(() => {
    return deckOrder.map(id => {
      const raw = files.read(`${id}/deck.json`);
      if (!raw) return null;
      try {
        const meta = typeof raw === 'string' ? JSON.parse(raw) : raw;
        return { id, ...meta };
      } catch {
        return null;
      }
    }).filter(Boolean);
  }, [files, deckOrder]);

  const currentSlide = slides[Math.min(currentSlideIndex, slides.length - 1)] || null;

  // Handlers
  const setCurrentSlideIndex = useCallback((index) => {
    if (!currentDeckId) return;
    const newIndex = typeof index === 'function' ? index(currentSlideIndex) : index;
    writeDeckMeta(currentDeckId, { currentSlideIndex: newIndex });
  }, [currentDeckId, currentSlideIndex, writeDeckMeta]);

  const setPresentationTitle = useCallback((title) => {
    if (!currentDeckId) return;
    writeDeckMeta(currentDeckId, { title });
  }, [currentDeckId, writeDeckMeta]);

  const handleCreateDeck = useCallback((title = 'New Presentation') => {
    const deckId = generateId('deck');
    const slideId = generateId('slide');
    
    files.write(`${deckId}/deck.json`, JSON.stringify({
      title,
      currentSlideIndex: 0,
      slideOrder: [slideId]
    }, null, 2));
    
    files.write(`${deckId}/${slideId}.html`, `<div style="display:flex;flex-direction:column;align-items:center;justify-content:center;height:100%;background:linear-gradient(135deg,#1e1e1e,#2d2d2d);padding:60px;">
  <h1 style="font-size:48px;font-weight:700;color:#fff;margin:0;text-align:center">${title}</h1>
  <p style="font-size:20px;color:#888;margin-top:16px">Click to edit</p>
</div>`);
    
    writeConfig({ currentDeckId: deckId, deckOrder: [...deckOrder, deckId] });
    return deckId;
  }, [files, writeConfig, deckOrder]);

  const handleDeleteDeck = useCallback((deckId) => {
    files.delete(`${deckId}/`);
    const newOrder = deckOrder.filter(id => id !== deckId);
    writeConfig({
      currentDeckId: deckId === currentDeckId ? (newOrder[0] || null) : currentDeckId,
      deckOrder: newOrder
    });
  }, [files, deckOrder, currentDeckId, writeConfig]);

  const handleSelectDeck = useCallback((deckId) => {
    writeConfig({ currentDeckId: deckId });
  }, [writeConfig]);

  const handleAddSlide = useCallback(() => {
    if (!currentDeckId || !currentDeckMeta) return;
    const slideId = generateId('slide');
    const num = (currentDeckMeta.slideOrder?.length || 0) + 1;
    
    files.write(`${currentDeckId}/${slideId}.html`, `<div style="display:flex;flex-direction:column;align-items:center;justify-content:center;height:100%;padding:60px;background:#fff">
  <h1 style="font-size:42px;font-weight:600;color:#1a1a1a;margin:0">Slide ${num}</h1>
  <p style="font-size:18px;color:#666;margin-top:12px">Add your content here</p>
</div>`);
    
    const newOrder = [...(currentDeckMeta.slideOrder || []), slideId];
    writeDeckMeta(currentDeckId, { slideOrder: newOrder, currentSlideIndex: newOrder.length - 1 });
  }, [files, currentDeckId, currentDeckMeta, writeDeckMeta]);

  const handleUpdateSlide = useCallback((slide) => {
    if (!currentDeckId) return;
    files.write(`${currentDeckId}/${slide.id}.html`, slide.content);
  }, [files, currentDeckId]);

  const handleDeleteSlide = useCallback((index) => {
    if (!currentDeckId || !currentDeckMeta || (currentDeckMeta.slideOrder?.length || 0) <= 1) return;
    const slideId = currentDeckMeta.slideOrder[index];
    if (!slideId) return;
    
    files.delete(`${currentDeckId}/${slideId}.html`);
    const newOrder = currentDeckMeta.slideOrder.filter((_, i) => i !== index);
    const newIndex = currentSlideIndex >= newOrder.length ? newOrder.length - 1 : 
                     currentSlideIndex > index ? currentSlideIndex - 1 : currentSlideIndex;
    writeDeckMeta(currentDeckId, { slideOrder: newOrder, currentSlideIndex: Math.max(0, newIndex) });
  }, [files, currentDeckId, currentDeckMeta, currentSlideIndex, writeDeckMeta]);

  const handleDuplicateSlide = useCallback((index) => {
    if (!currentDeckId || !currentDeckMeta?.slideOrder?.[index]) return;
    const sourceId = currentDeckMeta.slideOrder[index];
    const newId = generateId('slide');
    const content = files.read(`${currentDeckId}/${sourceId}.html`) || '';
    
    files.write(`${currentDeckId}/${newId}.html`, content);
    const newOrder = [...currentDeckMeta.slideOrder];
    newOrder.splice(index + 1, 0, newId);
    writeDeckMeta(currentDeckId, { slideOrder: newOrder, currentSlideIndex: index + 1 });
  }, [files, currentDeckId, currentDeckMeta, writeDeckMeta]);

  const handleReorderSlides = useCallback((from, to) => {
    if (!currentDeckId || !currentDeckMeta?.slideOrder) return;
    const newOrder = [...currentDeckMeta.slideOrder];
    const [moved] = newOrder.splice(from, 1);
    newOrder.splice(to, 0, moved);
    
    let newIndex = currentSlideIndex;
    if (currentSlideIndex === from) newIndex = to;
    else if (currentSlideIndex > from && currentSlideIndex <= to) newIndex--;
    else if (currentSlideIndex < from && currentSlideIndex >= to) newIndex++;
    
    writeDeckMeta(currentDeckId, { slideOrder: newOrder, currentSlideIndex: newIndex });
  }, [currentDeckId, currentDeckMeta, currentSlideIndex, writeDeckMeta]);

  const handleNavigate = useCallback((dir) => {
    if (dir === 'prev' && currentSlideIndex > 0) setCurrentSlideIndex(currentSlideIndex - 1);
    else if (dir === 'next' && currentSlideIndex < slides.length - 1) setCurrentSlideIndex(currentSlideIndex + 1);
  }, [currentSlideIndex, slides.length, setCurrentSlideIndex]);

  const handleExport = useCallback(() => {
    const html = exportSlidesToHTML(slides, presentationTitle);
    const blob = new Blob([html], { type: 'text/html' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `${presentationTitle.replace(/[^a-z0-9]/gi, '-').toLowerCase()}.html`;
    a.click();
    URL.revokeObjectURL(url);
  }, [slides, presentationTitle]);

  const handleExportPDF = useCallback(() => {
    exportSlidesToPDF(slides, presentationTitle);
  }, [slides, presentationTitle]);

  // Apply dark background
  useEffect(() => {
    document.body.style.background = '#0a0a0a';
    document.body.style.margin = '0';
    document.documentElement.style.minHeight = '100%';
    return () => {
      document.body.style.background = '';
      document.body.style.margin = '';
    };
  }, []);

  // Initialize if no decks
  useEffect(() => {
    if (!files.ready) return;
    if (config.deckOrder?.length > 0) {
      if (!config.currentDeckId || !config.deckOrder.includes(config.currentDeckId)) {
        writeConfig({ currentDeckId: config.deckOrder[0] });
      }
      return;
    }
    if (initRef.current) return;
    initRef.current = true;
    initializeDefaults(files);
  }, [files.ready, config, writeConfig]);

  return (
    <>
      <div style={{
        display: 'flex',
        flexDirection: 'column',
        height: '100%',
        width: '100%',
        fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif',
        backgroundColor: '#0a0a0a',
        overflow: 'hidden'
      }}>
        <HeaderBar
          presentationTitle={presentationTitle}
          onTitleChange={setPresentationTitle}
          onExport={handleExport}
          onExportPDF={handleExportPDF}
          deckCount={orderedDecks.length}
          onToggleDeckSidebar={() => setShowDeckSidebar(!showDeckSidebar)}
        />

        <div style={{ flex: 1, display: 'flex', overflow: 'hidden' }}>
          {/* Deck sidebar */}
          {showDeckSidebar && (
            <div style={{
              width: '180px',
              backgroundColor: '#0a0a0a',
              borderRight: '1px solid #262626',
              display: 'flex',
              flexDirection: 'column',
              overflow: 'hidden'
            }}>
              <div style={{
                padding: '10px 12px',
                borderBottom: '1px solid #262626',
                display: 'flex',
                justifyContent: 'space-between',
                alignItems: 'center'
              }}>
                <span style={{ color: '#737373', fontSize: '11px', fontWeight: 600, textTransform: 'uppercase' }}>
                  Decks
                </span>
                <button
                  onClick={() => handleCreateDeck()}
                  style={{
                    width: '20px',
                    height: '20px',
                    borderRadius: '4px',
                    border: '1px solid #404040',
                    backgroundColor: 'transparent',
                    color: '#a3a3a3',
                    cursor: 'pointer',
                    fontSize: '12px'
                  }}
                >
                  +
                </button>
              </div>
              <div style={{ flex: 1, overflowY: 'auto', padding: '8px' }}>
                {orderedDecks.map(deck => (
                  <div
                    key={deck.id}
                    onClick={() => handleSelectDeck(deck.id)}
                    style={{
                      padding: '8px 10px',
                      marginBottom: '4px',
                      borderRadius: '4px',
                      backgroundColor: deck.id === currentDeckId ? '#262626' : 'transparent',
                      cursor: 'pointer',
                      display: 'flex',
                      justifyContent: 'space-between',
                      alignItems: 'center'
                    }}
                  >
                    <div style={{ overflow: 'hidden' }}>
                      <div style={{
                        color: deck.id === currentDeckId ? '#fafafa' : '#a3a3a3',
                        fontSize: '12px',
                        fontWeight: 500,
                        overflow: 'hidden',
                        textOverflow: 'ellipsis',
                        whiteSpace: 'nowrap'
                      }}>
                        {deck.title}
                      </div>
                      <div style={{ color: '#525252', fontSize: '10px', marginTop: '2px' }}>
                        {deck.slideOrder?.length || 0} slides
                      </div>
                    </div>
                    {orderedDecks.length > 1 && (
                      <button
                        onClick={(e) => { e.stopPropagation(); handleDeleteDeck(deck.id); }}
                        style={{
                          background: 'none',
                          border: 'none',
                          color: '#525252',
                          cursor: 'pointer',
                          fontSize: '14px',
                          padding: '0 4px'
                        }}
                      >
                        ×
                      </button>
                    )}
                  </div>
                ))}
              </div>
            </div>
          )}

          <SlideThumbnails
            slides={slides}
            currentSlideIndex={currentSlideIndex}
            onSelectSlide={setCurrentSlideIndex}
            onDeleteSlide={handleDeleteSlide}
            onDuplicateSlide={handleDuplicateSlide}
            onReorderSlides={handleReorderSlides}
            onAddSlide={handleAddSlide}
          />

          <SlideEditor
            slide={currentSlide}
            slideIndex={currentSlideIndex}
            totalSlides={slides.length}
            onUpdateSlide={handleUpdateSlide}
            onNavigate={handleNavigate}
            onPresent={() => setIsPresenting(true)}
          />
        </div>
      </div>

      {isPresenting && slides.length > 0 && (
        <SlidePresenter
          slides={slides}
          initialSlideIndex={currentSlideIndex}
          onClose={() => setIsPresenting(false)}
        />
      )}

      <style>{`
        * { box-sizing: border-box; }
        ::-webkit-scrollbar { width: 6px; height: 6px; }
        ::-webkit-scrollbar-track { background: #171717; }
        ::-webkit-scrollbar-thumb { background: #404040; border-radius: 3px; }
        ::-webkit-scrollbar-thumb:hover { background: #525252; }
      `}</style>
    </>
  );
}

export default SlideDeckWidget;

